	//     "description": "Tickets that are assigned to Kelly",
	//     "active": true,
	//     "restriction": {
	//       "type": "User",
	//       "id": "213977756"
	//     },
	//     "all": [
	//       {
	//         "field": "status",
	//         "operator": "less_than",
	//         "value": "solved"
	//       },
