	//         "operator": "is",
	//         "value": "Canada"
	//       },
	//       ...
	//     ],
	//     "output": {
	//       "columns": ["status", "requester", "assignee"],
	//       "group_by": "assignee",
	//       "group_order": "desc",
	//       "sort_by": "status",
